   "comment": "婚纱",
   "content": "<performance_costume>\n\nform: \"婚纱形态\"\n\nappearance:\n\n  stage_wig:\n    description: \"演出时佩戴的专用假发，与日常发色形成区隔，是「Larimar」舞台身份的象征性元素\"\n  color: \"发色由原本的深色渐变转为更明亮的银白蓝调，整体接近冰蓝色月光，发尾沉入清透的海青与浅湖蓝\"\n  length: \"长发及腰以下，发量丰盈，发尾大幅度卷曲铺开\"\n  style:\n    bangs: \"刘海轻薄而柔顺，微微分束地落在额前，露出清澈蓝眸\"\n    side_hair: \"脸侧发丝自然垂落，带有柔软弧度，将脸型衬得更小巧\"\n    back_hair: \"后发大面积披散，卷度轻盈，发尾如海浪一样向外翻卷，蓝色渐变在末端最明显\"\n  ornament:\n    crown: \"头顶佩戴小巧的水晶王冠，通体为透明冰蓝色，像海水冻结后雕出的冠冕\"\n    hairpin: \"发侧点缀银白色花形发饰与细小晶片，像泡沫与星光落在发间\"\n\nface:\n  eyes: \"眼眸依旧是清澈浅蓝色，如海面反射天空，干净、明亮，没有半点阴影\"\n  expression: \"神情自信而柔和，带着天生偶像式的亲和力；不是刻意端出的高贵，而是理所当然站在光里的从容\"\n  skin: \"肤色白皙透亮，在浅蓝色婚纱映衬下更显冷白，像被晨光照亮的贝壳内壁\"\n\noutfit:\n  theme: \"海洋公主风婚纱，以纯白为主体，叠加浅蓝、湖蓝与亮青色裙摆，整体设计强调『透明感』『闪耀感』与『舞台展开感』\"\n\n  upper_body:\n    bodice:\n      type: \"无肩带束身式上衣\"\n      color: \"主体为纯白到浅冰蓝渐变\"\n      design: \"胸口上缘呈柔和弧线，中央有扇贝般展开的竖褶装饰，像一枚被打开的白色贝壳\"\n      fit: \"上身剪裁贴合，胸线与腰线被干净地收束，强调少女偶像纤细而挺拔的舞台轮廓\"\n      details: \"衣面带有淡淡珠光与暗纹刺绣，在光下会浮现细小花纹，如水面被风吹出的微纹\"\n\n    neckline:\n      choker: \"颈间佩戴白色蕾丝项圈，边缘有层叠细褶，中央垂下一枚水滴形蓝宝石吊坠\"\n      impression: \"项圈像一道精致的舞台标记，将锁骨与肩颈线条衬得更加清爽明亮\"\n\n    sleeves:\n      type: \"白色长手套\"\n      length: \"从上臂附近延伸至指尖，覆盖整条手臂\"\n      design: \"材质平滑贴合，肩部边缘有蕾丝花纹装饰，手腕与指尖线条修长\"\n\n  waist_and_skirt:\n    waist:\n      design: \"腰部收紧，周围环绕小片荷叶边与蝴蝶结装饰，像浪花在腰际打出的白色泡沫\"\n      silhouette: \"腰线被明确抬高，使腿部比例显得更加修长\"\n\n    front_skirt:\n      type: \"短款多层百褶裙\"\n      color: \"外层为白色，内侧隐约透出浅蓝与薄荷青\"\n      structure: \"前裙较短，层层百褶与荷叶边堆叠，带有明显的偶像婚纱感\"\n      details: \"裙摆边缘有细密蕾丝与波浪状裁边，像一圈圈细小浪花\"\n\n    back_train:\n      type: \"后方大拖尾裙摆\"\n      color: \"由纯白渐变到高饱和海蓝与青蓝\"\n      design: \"后摆大幅度展开，外白内蓝，层次像翻卷的海潮；内侧蓝色鲜明，外侧白色明亮，形成强烈舞台视觉\"\n      texture: \"布料轻而有支撑感，边缘带褶皱和卷边，像海浪被定格在最漂亮的一瞬\"\n      impression: \"前短后长的设计让她兼具少女偶像的轻快与公主礼服的华丽，转身时会像整片海色在身后展开\"\n\n  legwear:\n    thighhighs:\n      type: \"白色过膝长袜\"\n      color: \"纯白偏冷调，带轻微珠光\"\n      design: \"袜口处有精致蕾丝花纹，贴合大腿线条\"\n      zettai_ryouiki: \"短裙与过膝袜之间留出一截白皙肌肤，形成干净明亮的绝对领域，让舞台服在圣洁感中保留少女偶像的鲜活魅力\"\n\n  footwear:\n    boots:\n      type: \"白色系带高跟短靴\"\n      color: \"主体为纯白，细节处带浅蓝阴影\"\n      design: \"靴面有竖向系带与蕾丝装饰，鞋头圆润，鞋跟适中，兼顾华丽与稳定\"\n      details: \"靴口有小褶边与刺绣纹样，像把礼服的细节延续到脚尖\"\n\ncolor_palette:\n  main_colors:\n    - \"纯白\"\n    - \"冰蓝\"\n    - \"浅湖蓝\"\n    - \"海青色\"\n    - \"透明水晶蓝\"\n  visual_effect: \"整体色彩从上身的白与浅蓝，逐渐过渡到后裙摆的浓烈海蓝，像阳光照进海面，由浅滩一路延伸到深海\"\n\nidol_design:\n  concept: \"以『Larimar』这一艺名为核心，将海纹石、浪花、贝壳、水晶王冠与白色公主礼服融合成偶像婚纱\"\n  stage_presence: \"服装正面清爽轻盈，适合近景镜头；背后大面积蓝色拖尾则适合远景舞台，能在灯光下形成强烈识别度\"\n </performance_costume>",
